import xml.etree.ElementTree as ET

NS = "http://graphml.graphdrawing.org/xmlns"
ET.register_namespace("", NS)
REPO = "example/coolstore-weblogic"
q = lambda t: f"{{{NS}}}{t}"

cpg = ET.parse(f"{REPO}/cpg.graphml")
call = ET.parse(f"{REPO}/callgraph.graphml")
croot = cpg.getroot()
g = croot.find(q("graph"))

existing_keys = {k.get("id") for k in croot.findall(q("key"))}
for k in call.getroot().findall(q("key")):
    if k.get("id") not in existing_keys:
        croot.insert(len(croot.findall(q("key"))), k)

seen = {n.get("id") for n in g.findall(q("node"))}
for n in call.getroot().find(q("graph")).findall(q("node")):
    if n.get("id") not in seen:
        g.append(n)
        seen.add(n.get("id"))
for e in call.getroot().find(q("graph")).findall(q("edge")):
    g.append(e)

cpg.write(f"{REPO}/cpg.graphml", xml_declaration=True, encoding="UTF-8")
print(f"merged: {len(g.findall(q('node')))} nodes, {len(g.findall(q('edge')))} edges")
